<?php
require __DIR__.'/../includes/upb_bj_input_template.php';
function priorCheck($ok,$msg){if(!$ok)throw new RuntimeException($msg);}
function priorEdit($bytes,?callable $edit=null){$p=tempnam('/tmp','upb-prior-test-');try{file_put_contents($p,$bytes);$z=new ZipArchive();$z->open($p);$d=upbBjXml($z->getFromName('content.xml'));if(!$edit){$z->close();return $d;}$edit($d);$z->addFromString('content.xml',$d->saveXML());$z->close();return file_get_contents($p);}finally{unlink($p);}}
foreach([2026,2027] as $year){$prior=priorEdit(buildUpbBjInputTemplateOds(($year-1).'-12'),function($d){$i=0;foreach(upbBjTables($d) as $name=>$table){if($name==='KESIMPULAN')continue;$i++;$bottom=upbBjBottom($table);$cells=upbBjCells($table);foreach(['FARMASI'=>10000,'SOBISCO'=>1000,'CANDY'=>100] as $label=>$factor){$r=(int)substr($bottom[$label]['ref'],1);$cell=$cells[$r][9];$cell->setAttributeNS(UPB_O,'office:value',(string)($i*$factor));}}});
 $current=buildUpbBjInputTemplateOds($year.'-02');$out=buildUpbBjInputTemplateOds($year.'-02',$current,$prior);$d=priorEdit($out);$tables=upbBjTables($d);$cells=upbBjCells($tables['KESIMPULAN']);
 foreach(range(4,15) as $c){priorCheck((float)$cells[3][$c]->getAttributeNS(UPB_O,'value')===10.0,'Prior Farmasi per-month difference');priorCheck((float)$cells[4][$c]->getAttributeNS(UPB_O,'value')===1.0,'Prior Sobisco per-month');}
 priorCheck((float)$cells[3][16]->getAttributeNS(UPB_O,'value')===120.0,'Prior full-year total');priorCheck((float)$cells[3][2]->getAttributeNS(UPB_O,'value')===20.0,'Prior left YTD sums January through February');priorCheck((float)$cells[10][4]->getAttributeNS(UPB_O,'value')===0.0,'Current year remains empty');priorCheck($cells[3][5]->getAttributeNS(UPB_T,'formula')==="of:=(['_UPB_".($year-1)."'.B3]-['_UPB_".($year-1)."'.B2])/1000",'Valid previous-year references');priorCheck(isset($tables['_UPB_'.($year-1)]),'Previous-year source embedded');priorCheck($cells[3][2]->getAttributeNS(UPB_T,'formula')==='of:=SUM([.D3:.E3])','Left YTD uses simple January-February SUM');priorCheck($cells[6][2]->getAttributeNS(UPB_T,'formula')==='of:=SUM([.D6:.E6])','Total YTD also uses monthly SUM');
 $style=null;foreach($d->getElementsByTagNameNS('urn:oasis:names:tc:opendocument:xmlns:style:1.0','style') as $node)if($node->getAttributeNS('urn:oasis:names:tc:opendocument:xmlns:style:1.0','name')==='UPBSummaryPriorHidden')$style=$node;priorCheck($style&&$style->getElementsByTagNameNS('urn:oasis:names:tc:opendocument:xmlns:style:1.0','table-properties')->item(0)->getAttributeNS(UPB_T,'display')==='false','Prior source hidden');validateUpbBjOds($out,$year.'-02');file_put_contents('/tmp/upb-prior-'.$year.'.ods',$out);
}
echo "PASS: prior-year monthly differences/full year, formulas, hidden sources, current year isolation and year rollover.\n";
